 static func request(base:String,token:String,path:String,body:[String:Any]?=nil)async throws->Data {let root=try canonical(base);guard token.count>=32,token.count<=512,!token.contains("\n"),!token.contains("\r"),allowedPath(path),(body==nil || ["v1/preview","v1/submit","v1/cancel"].contains(path))else{throw StrategyError.invalid("서버 토큰/요청 확인 필요")};var request=URLRequest(url:URL(string:root.absoluteString.trimmingCharacters(in:CharacterSet(charactersIn:"/"))+"/"+path)!);request.timeoutInterval=15;request.setValue("Bearer "+token,forHTTPHeaderField:"Authorization");request.setValue("application/json",forHTTPHeaderField:"Accept");if let body=body{request.httpMethod="POST";request.setValue("application/json",forHTTPHeaderField:"Content-Type");request.httpBody=try JSONSerialization.data(withJSONObject:body)};let config=URLSessionConfiguration.ephemeral;config.timeoutIntervalForResource=20;let delegate=NoTradeRedirects();let session=URLSession(configuration:config,delegate:delegate,delegateQueue:nil);defer{session.invalidateAndCancel()};let(data,response)=try await session.data(for:request);guard data.count<=1024*1024,let http=response as? HTTPURLResponse else{throw StrategyError.invalid("서버 응답 형식 오류")};guard http.statusCode==200 else{if http.statusCode==401 || http.statusCode==403{throw StrategyError.invalid("서버 토큰/읽기·제어 권한을 확인하세요")};if http.statusCode==404{throw StrategyError.invalid("주문 기록/거래 서버 경로 확인 필요")};if http.statusCode==503{throw StrategyError.invalid("거래소/서버 응답 불명 · 제출 후에는 주문 상태부터 확인하세요")};if http.statusCode==409{throw StrategyError.invalid("실주문 비활성·검토 만료·금액/정밀도·미확인 주문을 서버에서 확인하세요")};throw StrategyError.invalid("서버 응답 오류 (\(http.statusCode))")};return data}
